<template><section aria-label="二维码工具"><p class="tool-note">生成网址或文字二维码，或从静态图片识别二维码。图片和内容仅在浏览器本地处理；识别结果不会自动打开。</p><div class="tool-two-column"><div><label class="tool-label">二维码内容<textarea v-model="input" aria-label="二维码内容" placeholder="输入网址或文字"></textarea></label><div class="tool-actions"><label>尺寸<select v-model.number="size" aria-label="二维码尺寸"><option :value="256">256 px</option><option :value="384">384 px</option><option :value="512">512 px</option><option :value="768">768 px</option></select></label><label>纠错<select v-model="level" aria-label="二维码纠错级别"><option value="L">L</option><option value="M">M</option><option value="Q">Q</option><option value="H">H</option></select></label><button type="button" :disabled="generating||!input" @click="generate">生成二维码</button></div><div v-show="generated" class="qr-preview"><canvas ref="canvas" aria-label="生成的二维码"></canvas></div><p v-if="stale" class="tool-note">内容或设置已更改，请重新生成二维码。</p><button type="button" :disabled="!blob||stale" @click="download">下载二维码 PNG</button><p role="status">{{message}}</p></div><div><label class="tool-label">选择二维码图片<input type="file" accept="image/png,image/jpeg,image/webp,image/bmp,image/avif" aria-label="选择二维码图片" @change="readImage" /></label><p class="tool-note">支持 PNG、JPEG、WebP、BMP、AVIF 静态图，最多 10 MiB；建议使用清晰、留有完整边框的二维码。</p><label class="tool-label">识别结果<textarea v-model="decoded" aria-label="二维码识别结果" readonly></textarea></label><button type="button" :disabled="!decoded" @click="copyDecoded">复制识别结果</button><p role="status">{{reading?'正在识别…':decodeMessage}}</p></div></div></section></template>
<script>
import { downloadBlob } from '../../utils/utility-tools.mjs';
export default {
  name:'QrTool',data:()=>({input:'',size:384,level:'M',generating:false,generated:false,blob:null,signature:'',message:'',decoded:'',decodeMessage:'',reading:false,renderRequest:0,readRequest:0}),
  computed:{stale(){return this.generated&&this.signature!==JSON.stringify([this.input,this.size,this.level]);}},
  beforeUnmount(){++this.renderRequest;++this.readRequest;},
  methods:{
    async generate(){const request=++this.renderRequest;const text=this.input,size=this.size,level=this.level;this.generating=true;this.blob=null;this.message='';try{if(new TextEncoder().encode(text).length>2000)throw Error('内容超过 2000 UTF-8 字节，请缩短');const module=await import('qrcode');const qr=module.default||module;if(request!==this.renderRequest)return;await qr.toCanvas(this.$refs.canvas,text,{width:size,margin:4,errorCorrectionLevel:level,color:{dark:'#000000ff',light:'#ffffffff'}});const blob=await new Promise(resolve=>this.$refs.canvas.toBlob(resolve,'image/png'));if(request!==this.renderRequest)return;if(!blob)throw Error('二维码导出失败');this.blob=blob;this.generated=true;this.signature=JSON.stringify([text,size,level]);this.message='二维码已生成';}catch(error){if(request===this.renderRequest){this.generated=false;this.message='生成失败：'+error.message;}}finally{if(request===this.renderRequest)this.generating=false;}},
    download(){if(this.blob&&!this.stale)downloadBlob(this.blob,'01-qrcode.png');},
    async readImage(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const request=++this.readRequest;this.reading=true;this.decoded='';this.decodeMessage='';let bitmap;try{if(file.size>10*1024*1024)throw Error('图片超过 10 MiB');if(!['image/png','image/jpeg','image/webp','image/bmp','image/avif'].includes(file.type))throw Error('请选择受支持的静态图片');bitmap=await createImageBitmap(file);if(request!==this.readRequest)return;if(bitmap.width*bitmap.height>24000000)throw Error('图片超过 2400 万像素，请先裁剪');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height);const module=await import('jsqr');if(request!==this.readRequest)return;const jsQR=module.default||module;const result=jsQR(data.data,data.width,data.height,{inversionAttempts:'attemptBoth'});this.decoded=result?.data||'';this.decodeMessage=result?'识别成功；内容不会自动打开':'未识别到二维码，请尝试更清晰或裁剪后的图片';}catch(error){if(request===this.readRequest)this.decodeMessage='识别失败：'+error.message;}finally{bitmap?.close();if(request===this.readRequest)this.reading=false;}},
    async copyDecoded(){try{await navigator.clipboard.writeText(this.decoded);this.decodeMessage='已复制识别结果';}catch{this.decodeMessage='复制未完成，请选择文字手动复制';}}
  }
};
</script>
<style scoped>.qr-preview{padding:12px;background:#fff;border:1px solid var(--el-border-color);border-radius:10px;text-align:center;margin-bottom:12px;}.qr-preview canvas{max-width:100%;height:auto;image-rendering:pixelated;}</style>
